/*
 * shared/hooks/useOnboardingExitGuard.js. The web pushes a history entry and
 * catches "popstate"; the app catches the hardware back button the same way:
 * first step -> ask before leaving, later steps -> previous step.
 */
function useOnboardingExitGuard({ isFirstStep, onPreviousStep, onExit, hasUnsavedProgress = () => true }) {
  const [showExitModal, setShowExitModal] = useState(false)

  const handleStay = useCallback(() => {
    setShowExitModal(false)
  }, [])

  const handleExit = useCallback(() => {
    setShowExitModal(false)
    onExit?.()
  }, [onExit])

  const requestExit = useCallback(() => {
    if (hasUnsavedProgress()) {
      setShowExitModal(true)
      return
    }
    onExit?.()
  }, [hasUnsavedProgress, onExit])

  const handleBack = useCallback(() => {
    if (isFirstStep) {
      requestExit()
      return
    }
    onPreviousStep?.()
  }, [isFirstStep, onPreviousStep, requestExit])

  useEffect(() => {
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      if (isFirstStep) {
        requestExit()
        return true
      }
      onPreviousStep?.()
      return true
    })
    return () => sub.remove()
  }, [isFirstStep, onPreviousStep, requestExit])

  return { showExitModal, handleBack, handleStay, handleExit, requestExit }
}

const saveFileToDB = async (key, file) => {
  if (!file || !isUploadableFile(file)) return
  try {
    const { uri, name, type, size, width, height } = file
    localStore.setItem(ONBOARDING_FILE_KEY_PREFIX + key, JSON.stringify({ uri, name, type, size, width, height }))
  } catch (err) {
    debugError("Saving picked file failed:", err)
  }
}

const getFileFromDB = async (key) => {
  try {
    const raw = localStore.getItem(ONBOARDING_FILE_KEY_PREFIX + key)
    const file = raw ? JSON.parse(raw) : null
    return isUploadableFile(file) ? file : null
  } catch (err) {
    debugError("Loading picked file failed:", err)
    return null
  }
}

const deleteFileFromDB = async (key) => {
  try {
    localStore.removeItem(ONBOARDING_FILE_KEY_PREFIX + key)
  } catch (err) {
    debugError("Deleting picked file failed:", err)
  }
}

