/*
 * Location search. The web attaches the Google Places widget to the input (strictly inside the chosen
 * zone) and falls back to Nominatim suggestions; the app has no widget, so it asks the geocode proxy's
 * text search (biased to the chosen zone) and fills the same fields from the picked place.
 */
const skipSearchRef = useRef("")

const zoneCenter = (zone) => {
  const points = (Array.isArray(zone?.coordinates) ? zone.coordinates : [])
    .map((c) => ({ lat: parseFloat(c.latitude ?? c.lat), lng: parseFloat(c.longitude ?? c.lng) }))
    .filter((p) => Number.isFinite(p.lat) && Number.isFinite(p.lng))
  if (!points.length) return null
  return {
    latitude: points.reduce((sum, p) => sum + p.lat, 0) / points.length,
    longitude: points.reduce((sum, p) => sum + p.lng, 0) / points.length,
  }
}

useEffect(() => {
  if (step !== 1) return
  const q = String(locationSearchValue || "").trim()

  if (skipSearchRef.current && skipSearchRef.current === q) return
  skipSearchRef.current = ""

  if (q.length < 3) {
    setLocationSuggestions([])
    setIsSearchingLocation(false)
    return
  }

  const selectedZone = zones.find(z => String(z?._id || z?.id) === String(step1.zoneId))
  const zoneName = selectedZone?.name || selectedZone?.zoneName || selectedZone?.serviceLocation || ""
  let cancelled = false

  const t = setTimeout(async () => {
    try {
      setIsSearchingLocation(true)
      const queryWithZone = zoneName ? `${q}, ${zoneName}` : q
      const res = await geocodeAPI.textSearch({ textQuery: queryWithZone, maxResultCount: 8, ...(zoneCenter(selectedZone) || {}) })
      const places = res?.data?.data?.places
      const mapped = (Array.isArray(places) ? places : []).map((p) => ({
        id: p.id,
        display: [p.displayName?.text, p.formattedAddress].filter(Boolean).join(", ") || p.formattedAddress || "",
        formattedAddress: p.formattedAddress || "",
        lat: Number(p.location?.latitude),
        lng: Number(p.location?.longitude),
      }))
      if (!cancelled) setLocationSuggestions(mapped)
    } catch (e) {
      debugError("Location search failed:", e)
    } finally {
      if (!cancelled) setIsSearchingLocation(false)
    }
  }, 400)

  return () => {
    cancelled = true
    clearTimeout(t)
  }
}, [locationSearchValue, step, step1.zoneId, zones])

const selectLocationSuggestion = async (s) => {
  skipSearchRef.current = s.display
  setLocationSearchValue(s.display)
  setLocationSuggestions([])
  Keyboard.dismiss()

  // parsePlace() of the web's autocomplete handler, on the geocoded place's address components
  let parsed = { area: "", city: "", state: "", pincode: "" }
  try {
    const res = await geocodeAPI.place(s.id)
    const comps = res?.data?.data?.results?.[0]?.address_components
    if (Array.isArray(comps)) {
      const get = (types) => comps.find((c) => types.some((t) => c.types?.includes(t)))?.long_name || ""
      parsed = {
        area: get(["sublocality_level_1", "sublocality", "neighborhood"]) || get(["locality"]),
        city: get(["locality"]) || get(["administrative_area_level_2"]),
        state: get(["administrative_area_level_1"]) || get(["administrative_area_level_2"]),
        pincode: get(["postal_code"]),
      }
    }
  } catch (e) {
    debugError("Place details failed:", e)
  }

  setStep1((prev) => ({
    ...prev,
    location: {
      ...prev.location,
      formattedAddress: s.formattedAddress || s.display || prev.location.formattedAddress,
      addressLine1: s.formattedAddress || s.display || prev.location.addressLine1 || "",
      area: parsed.area || prev.location.area,
      city: parsed.city || prev.location.city,
      state: parsed.state || prev.location.state,
      pincode: parsed.pincode || prev.location.pincode,
      latitude: Number.isFinite(s.lat) ? Number(s.lat.toFixed(6)) : prev.location.latitude,
      longitude: Number.isFinite(s.lng) ? Number(s.lng.toFixed(6)) : prev.location.longitude,
    },
  }))
}
